import java.util.*;

public class Solution {
    /**
     * Checks whether any two numbers in the given list are closer to each other
     * than the specified threshold.
     *
     * @param numbers   the list of numbers to examine
     * @param threshold the distance threshold
     * @return {@code true} if there exists a pair of numbers whose absolute
     *         difference is strictly less than {@code threshold},
     *         otherwise {@code false}
     */
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
        if (numbers == null || numbers.size() < 2 || threshold <= 0) {
            return false;
        }

        // Create a sorted copy of the list
        List<Double> sorted = new ArrayList<>(numbers);
        Collections.sort(sorted);

        // Check adjacent pairs in the sorted list
        for (int i = 1; i < sorted.size(); i++) {
            double diff = Math.abs(sorted.get(i) - sorted.get(i - 1));
            if (diff < threshold) {
                return true;
            }
        }
        return false;
    }
}
