import java.util.*;

public class Solution {
    public boolean hasCloseElements(List<Double> numbers, double threshold) {
        // Quick checks
        if (numbers == null || numbers.size() < 2 || threshold <= 0) {
            return false;
        }

        // Copy the list into an array for sorting
        double[] arr = new double[numbers.size()];
        for (int i = 0; i < numbers.size(); i++) {
            arr[i] = numbers.get(i);
        }

        // Sort the array so that close elements become adjacent
        Arrays.sort(arr);

        // Check adjacent pairs for a distance smaller than the threshold
        for (int i = 1; i < arr.length; i++) {
            if (Math.abs(arr[i] - arr[i - 1]) < threshold) {
                return true;
            }
        }

        return false;
    }
}
