import java.util.List;

public class Solution {

    /**
     * Calculates the Mean Absolute Deviation (MAD) of a list of numbers.
     *
     * @param numbers the list of Double values
     * @return the MAD as a double; returns 0.0 if the list is empty
     */
    public double meanAbsoluteDeviation(List<Double> numbers) {
        int n = numbers.size();
        if (n == 0) {
            return 0.0;
        }

        // Compute the mean
        double sum = 0.0;
        for (double value : numbers) {
            sum += value;
        }
        double mean = sum / n;

        // Compute the average absolute deviation
        double absDiffSum = 0.0;
        for (double value : numbers) {
            absDiffSum += Math.abs(value - mean);
        }

        return absDiffSum / n;
    }
}
