import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Integer> intersperse(List<Integer> numbers, int delimiter) {
        if (numbers == null || numbers.isEmpty()) {
            return List.of();
        }

        // Pre‑allocate capacity: each element plus a delimiter between them
        int capacity = numbers.size() + Math.max(0, numbers.size() - 1);
        List<Integer> result = new ArrayList<>(capacity);

        for (int i = 0; i < numbers.size() - 1; i++) {
            result.add(numbers.get(i));
            result.add(delimiter);
        }
        // Add the last element (no delimiter after it)
        result.add(numbers.get(numbers.size() - 1));

        return result;
    }
}
