import java.util.ArrayList;
import java.util.List;

public class Solution {

    /**
     * Parses a string containing multiple groups of nested parentheses separated by spaces.
     * For each group, computes the deepest level of nesting of parentheses.
     *
     * @param parenString the input string containing groups of parentheses
     * @return a list of integers where each integer represents the maximum nesting depth
     *         for the corresponding group
     */
    public List<Integer> parseNestedParens(String parenString) {
        List<Integer> result = new ArrayList<>();

        if (parenString == null || parenString.isEmpty()) {
            return result;
        }

        // Split on one or more whitespace characters
        String[] groups = parenString.trim().split("\\s+");

        for (String group : groups) {
            int maxDepth = 0;
            int currentDepth = 0;

            for (int i = 0; i < group.length(); i++) {
                char c = group.charAt(i);
                if (c == '(') {
                    currentDepth++;
                    if (currentDepth > maxDepth) {
                        maxDepth = currentDepth;
                    }
                } else if (c == ')') {
                    currentDepth--;
                    // In a well‑formed string currentDepth should never go negative
                }
            }

            result.add(maxDepth);
        }

        return result;
    }
}
