public class Solution {

    /**
     * Returns the shortest palindrome that starts with the given string.
     *
     * @param s the original string
     * @return the shortest palindrome beginning with s
     */
    public String makePalindrome(String s) {
        if (s == null || s.isEmpty()) {
            return "";
        }

        int n = s.length();
        int start = 0; // index where the longest palindromic suffix starts

        // Find the longest suffix that is a palindrome
        for (int i = 0; i < n; i++) {
            if (isPalindrome(s, i, n - 1)) {
                start = i;
                break;
            }
        }

        // Prefix before the palindromic suffix
        String prefix = s.substring(0, start);
        String reversedPrefix = new StringBuilder(prefix).reverse().toString();

        return s + reversedPrefix;
    }

    /**
     * Checks if the substring s[l..r] (inclusive) is a palindrome.
     */
    private boolean isPalindrome(String s, int l, int r) {
        while (l < r) {
            if (s.charAt(l) != s.charAt(r)) {
                return false;
            }
            l++;
            r--;
        }
        return true;
    }
}
