public class Solution {

    /**
     * Returns the greatest common divisor (GCD) of two integers.
     * The GCD is defined for non‑negative integers; negative inputs are treated as their absolute values.
     *
     * @param a first integer
     * @param b second integer
     * @return the greatest common divisor of a and b
     */
    public int greatestCommonDivisor(int a, int b) {
        // Treat negative numbers as positive
        a = Math.abs(a);
        b = Math.abs(b);

        // If both are zero, GCD is undefined; return 0 for convenience
        if (a == 0 && b == 0) {
            return 0;
        }

        // Euclidean algorithm (iterative implementation)
        while (b != 0) {
            int temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }
}
