public class Solution {

    /**
     * Checks whether the given string is a palindrome.
     *
     * @param s the string to check
     * @return true if s is a palindrome, false otherwise
     */
    private boolean isPalindrome(String s) {
        int i = 0;
        int j = s.length() - 1;
        while (i < j) {
            if (s.charAt(i) != s.charAt(j)) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }

    /**
     * Returns the shortest palindrome that starts with the supplied string.
     *
     * @param string the original string
     * @return the shortest palindrome beginning with string
     */
    public String makePalindrome(String string) {
        if (string == null || string.isEmpty()) {
            return "";
        }

        int startOfSuffix = 0;
        // Find the longest suffix that is a palindrome
        while (!isPalindrome(string.substring(startOfSuffix))) {
            startOfSuffix++;
        }

        // Append the reverse of the prefix before that suffix
        String prefix = string.substring(0, startOfSuffix);
        StringBuilder sb = new StringBuilder(prefix);
        sb.reverse();

        return string + sb.toString();
    }
}
