public class Solution {
    public List<Integer> parseMusic(String string) {
        List<Integer> result = new ArrayList<>();
        if (string == null || string.isBlank()) {
            return result;
        }

        // Split on one or more whitespace characters to handle multiple spaces
        String[] notes = string.trim().split("\\s+");
        for (String note : notes) {
            switch (note) {
                case "o":
                    result.add(4);   // whole note
                    break;
                case "o|":
                    result.add(2);   // half note
                    break;
                case ".|":
                    result.add(1);   // quarter note
                    break;
                // If an unexpected token appears, it is ignored
            }
        }
        return result;
    }
}
