import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class Solution {
    public List<Double> findClosestElements(List<Double> numbers) {
        if (numbers == null || numbers.size() < 2) {
            throw new IllegalArgumentException("Input list must contain at least two numbers.");
        }

        double minDiff = Double.MAX_VALUE;
        double first = 0.0;
        double second = 0.0;

        for (int i = 0; i < numbers.size(); i++) {
            for (int j = i + 1; j < numbers.size(); j++) {
                double diff = Math.abs(numbers.get(i) - numbers.get(j));
                if (diff < minDiff) {
                    minDiff = diff;
                    first = numbers.get(i);
                    second = numbers.get(j);
                }
            }
        }

        List<Double> result = new ArrayList<>(2);
        result.add(first);
        result.add(second);
        Collections.sort(result);   // ensures smaller number first
        return result;
    }
}
