import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    public List<Double> rescaleToUnit(List<Double> numbers) {
        double min = Collections.min(numbers);
        double max = Collections.max(numbers);
        double range = max - min;

        List<Double> result = new ArrayList<>(numbers.size());
        for (double value : numbers) {
            // If all numbers are equal, avoid division by zero; map all to 0.0
            double scaled = range == 0 ? 0.0 : (value - min) / range;
            result.add(scaled);
        }
        return result;
    }
}
