            throw new IllegalArgumentException("Input list must not be null or empty");
        }

        double min = Collections.min(numbers);
        double max = Collections.max(numbers);

        if (max == min) {
            throw new IllegalArgumentException("All numbers are equal; cannot rescale to unit interval");
        }

        double range = max - min;
        List<Double> result = new ArrayList<>(numbers.size());

        for (Double value : numbers) {
            result.add((value - min) / range);
        }

        return result;
    }
}
