import java.util.*;

class Solution {
    /**
     * Returns the largest integer that divides {@code n} evenly and is smaller than {@code n}.
     * If {@code n} is 1, the method returns 1.
     *
     * @param n the number to find the largest divisor for
     * @return the largest divisor of n that is less than n
     */
    public int largestDivisor(int n) {
        if (n <= 1) {
            return 1; // for n == 1 the only divisor smaller than n is 1 itself
        }

        // The largest possible proper divisor is at most n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        // Should never reach here because 1 always divides n
        return 1;
    }
}
