import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<Integer> factorize(int n) {
        List<Integer> factors = new ArrayList<>();
        if (n <= 1) {
            return factors; // no prime factors for 0, 1 or negative numbers
        }

        // Handle factor 2 separately to allow incrementing i by 2 later
        while (n % 2 == 0) {
            factors.add(2);
            n /= 2;
        }

        // Check odd factors from 3 upwards
        for (int i = 3; i * i <= n; i += 2) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
        }

        // If n is now a prime number greater than 2, add it
        if (n > 1) {
            factors.add(n);
        }

        return factors;
    }
}
