import java.util.*;

class Solution {
    public List<Integer> sortThird(List<Integer> l) {
        // Create a copy so the original list is not modified
        List<Integer> result = new ArrayList<>(l);

        // Collect the elements at indices divisible by 3
        List<Integer> thirds = new ArrayList<>();
        for (int i = 0; i < result.size(); i += 3) {
            thirds.add(result.get(i));
        }

        // Sort those collected elements
        Collections.sort(thirds);

        // Put the sorted values back into the result list
        for (int i = 0; i < result.size(); i += 3) {
            result.set(i, thirds.get(i / 3));
        }

        return result;
    }
}
