import java.util.*;

public class Solution {

    /**
     * Evaluates a polynomial with coefficients xs at point x.
     * The polynomial is defined as:
     *   f(x) = xs[0] + xs[1] * x + xs[2] * x^2 + ... + xs[n] * x^n
     *
     * @param xs  list of coefficients (index i corresponds to coefficient of x^i)
     * @param x   the point at which to evaluate the polynomial
     * @return    the value of the polynomial at x
     */
    public double poly(List<Double> xs, double x) {
        double result = 0.0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
     * Finds a real root of the polynomial defined by the coefficient list xs.
     * The list must contain an even number of coefficients and the leading
     * (highest-degree) coefficient must be non‑zero, guaranteeing at least
     * one real root.
     *
     * @param xs  list of coefficients (index i corresponds to coefficient of x^i)
     * @return    one real root of the polynomial
     */
    public double findZero(List<Double> xs) {
        double begin = -1.0;
        double end   =  1.0;

        // Expand the interval until it brackets a root
        while (poly(xs, begin) * poly(xs, end) > 0) {
            begin *= 2.0;
            end   *= 2.0;
        }

        // Bisection method
        while (end - begin > 1e-10) {
            double mid = (begin + end) / 2.0;
            if (poly(xs, begin) * poly(xs, mid) > 0) {
                begin = mid;
            } else {
                end = mid;
            }
        }

        return begin;  // or (begin + end) / 2.0 for a slightly more accurate midpoint
    }
}
