import java.util.List;

public class Solution {

    /**
     * Finds a real root of the polynomial defined by the coefficient list {@code xs}.
     * The list contains coefficients in ascending order of degree:
     * xs.get(0) + xs.get(1)*x + xs.get(2)*x^2 + ...
     *
     * @param xs list of coefficients (must contain an odd number of elements)
     * @return one real root of the polynomial
     */
    public double findZero(List<Double> xs) {
        // Evaluate polynomial using Horner's method
        java.util.function.DoubleUnaryOperator poly = x -> {
            double result = 0.0;
            for (int i = xs.size() - 1; i >= 0; i--) {
                result = result * x + xs.get(i);
            }
            return result;
        };

        // Find an interval [low, high] where the polynomial changes sign.
        double low = -1.0;
        double high = 1.0;
        double fLow = poly.applyAsDouble(low);
        double fHigh = poly.applyAsDouble(high);

        // Expand the interval until a sign change is found.
        int expansion = 0;
        while (fLow * fHigh > 0 && expansion < 1000) {
            low *= 2.0;
            high *= 2.0;
            fLow = poly.applyAsDouble(low);
            fHigh = poly.applyAsDouble(high);
            expansion++;
        }

        // If we still don't have a sign change, fall back to a large interval.
        if (fLow * fHigh > 0) {
            low = -1e6;
            high = 1e6;
            fLow = poly.applyAsDouble(low);
            fHigh = poly.applyAsDouble(high);
        }

        // If one endpoint is exactly zero, return it.
        if (Math.abs(fLow) < 1e-14) return low;
        if (Math.abs(fHigh) < 1e-14) return high;

        // Bisection method
        final double tolerance = 1e-12;
        while (high - low > tolerance) {
            double mid = (low + high) / 2.0;
            double fMid = poly.applyAsDouble(mid);

            if (Math.abs(fMid) < 1e-14) {
                return mid;
            }

            if (fLow * fMid < 0) {
                high = mid;
                fHigh = fMid;
            } else {
                low = mid;
                fLow = fMid;
            }
        }

        return (low + high) / 2.0;
    }
}
