import java.util.*;

public class Solution {
    public List<Integer> sortThird(List<Integer> l) {
        // Create a mutable copy of the input list
        List<Integer> result = new ArrayList<>(l);

        // Collect indices divisible by 3 and their corresponding values
        List<Integer> indices = new ArrayList<>();
        List<Integer> values  = new ArrayList<>();

        for (int i = 0; i < l.size(); i++) {
            if (i % 3 == 0) {
                indices.add(i);
                values.add(l.get(i));
            }
        }

        // Sort the collected values
        Collections.sort(values);

        // Place the sorted values back into the result list
        for (int i = 0; i < indices.size(); i++) {
            result.set(indices.get(i), values.get(i));
        }

        return result;
    }
}
