import java.util.List;

public class Solution {

    /**
     * Evaluates a polynomial with coefficients xs at point x.
     * The polynomial is defined as:
     *   f(x) = xs[0] + xs[1] * x + xs[2] * x^2 + ... + xs[n] * x^n
     *
     * @param xs  list of coefficients (index i corresponds to the coefficient of x^i)
     * @param x   the point at which to evaluate the polynomial
     * @return    the value of the polynomial at x
     */
    public double poly(List<Double> xs, double x) {
        double result = 0.0;
        for (int i = 0; i < xs.size(); i++) {
            result += xs.get(i) * Math.pow(x, i);
        }
        return result;
    }

    /**
     * Finds a real root of the polynomial defined by the coefficient list xs.
     * The list must contain an even number of coefficients (i.e., the polynomial
     * degree is odd), guaranteeing at least one real root.
     *
     * @param xs  list of coefficients (index i corresponds to the coefficient of x^i)
     * @return    one real root of the polynomial
     */
    public double findZero(List<Double> xs) {
        double begin = -1.0;
        double end   =  1.0;
        double fBegin = poly(xs, begin);
        double fEnd   = poly(xs, end);

        // Expand the interval until the function values at the ends have opposite signs
        while (fBegin * fEnd > 0) {
            begin *= 2.0;
            end   *= 2.0;
            fBegin = poly(xs, begin);
            fEnd   = poly(xs, end);
        }

        // If we hit an exact zero, return it immediately
        if (Math.abs(fBegin) < 1e-12) return begin;
        if (Math.abs(fEnd)   < 1e-12) return end;

        // Bisection method
        final double tolerance = 1e-10;
        while (Math.abs(begin - end) > tolerance) {
            double mid = (begin + end) / 2.0;
            double fMid = poly(xs, mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid; // found exact root
            }

            // Decide which subinterval contains the root
            if (fBegin * fMid < 0) {
                end = mid;
                fEnd = fMid;
            } else {
                begin = mid;
                fBegin = fMid;
            }
        }

        // Return the midpoint of the final interval as the root approximation
        return (begin + end) / 2.0;
    }
}
