class Solution {
    public List<Integer> sortThird(List<Integer> l) {
        // Create a copy of the original list to avoid mutating the input
        List<Integer> result = new ArrayList<>(l);

        // Collect the elements at indices divisible by 3
        List<Integer> thirds = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 3) {
            thirds.add(l.get(i));
