        for (int i = 0; i < l.size(); i += 2) {
            evens.add(l.get(i));
        }

        // Sort the even values
        Collections.sort(evens);

        // Build the result list
        List<Integer> result = new ArrayList<>(l.size());
        int evenIdx = 0;
        for (int i = 0; i < l.size(); i++) {
            if (i % 2 == 0) {
                result.add(evens.get(evenIdx++));
            } else {
                result.add(l.get(i));
            }
        }

        return result;
    }
}

