import java.util.ArrayList;
import java.util.List;

public class Solution {

    /**
     * Encodes the input string by cycling groups of three characters.
     * Each group of exactly three characters is rotated left by one position.
     * Groups with fewer than three characters are left unchanged.
     */
    public String encodeCyclic(String s) {
        List<String> groups = new ArrayList<>();
        for (int i = 0; i < s.length(); i += 3) {
            groups.add(s.substring(i, Math.min(i + 3, s.length())));
        }
        for (int i = 0; i < groups.size(); i++) {
            String g = groups.get(i);
            if (g.length() == 3) {
                groups.set(i, g.substring(1) + g.charAt(0));
            }
        }
        return String.join("", groups);
    }

    /**
     * Decodes a string that was encoded with {@link #encodeCyclic(String)}.
     * The decoding reverses the left rotation performed on each full group of three characters.
     */
    public String decodeCyclic(String s) {
        List<String> groups = new ArrayList<>();
        for (int i = 0; i < s.length(); i += 3) {
            groups.add(s.substring(i, Math.min(i + 3, s.length())));
        }
        for (int i = 0; i < groups.size(); i++) {
            String g = groups.get(i);
            if (g.length() == 3) {
                groups.set(i, g.charAt(2) + g.substring(0, 2));
            }
        }
        return String.join("", groups);
    }
}
