class Solution {
    public int primeFib(int n) {
        long f0 = 0, f1 = 1;
        while (true) {
            long p = f0 + f1;
            if (p >= 2 && isPrime(p)) {
                n--;
                if (n == 0) {
                    return (int) p;
                }
            }
            f0 = f1;
            f1 = p;
        }
    }

    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0) return false;
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}
