class Solution {
    public int primeFib(int n) {
        long f0 = 0, f1 = 1;   // Fibonacci seeds
        int count = 0;         // how many prime Fibonacci numbers found

        while (true) {
            long p = f0 + f1;  // next Fibonacci number
            f0 = f1;
            f1 = p;

            if (isPrime(p)) {
                count++;
                if (count == n) {
                    return (int) p;   // result fits in int for the expected n
                }
            }
        }
    }

    // Helper method to test primality of a long value
    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0 || num % 3 == 0) return false;

        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) return false;
        }
        return true;
    }
}
