import java.util.*;

public class Solution {
    /**
     * Decodes a string that was encoded by {@code encodeCyclic}.
     * The encoding performs a cyclic shift of each alphabetic character
     * by +1 (with wrap‑around).  This method reverses that shift.
     *
     * @param s the encoded string
     * @return the decoded string
     */
    public String decodeCyclic(String s) {
        if (s == null || s.isEmpty()) {
            return s;
        }

        StringBuilder decoded = new StringBuilder(s.length());

        for (char c : s.toCharArray()) {
            if (c >= 'a' && c <= 'z') {
                // shift back by 1, wrap around from 'a' to 'z'
                decoded.append((char) ('a' + (c - 'a' + 25) % 26));
            } else if (c >= 'A' && c <= 'Z') {
                // shift back by 1, wrap around from 'A' to 'Z'
                decoded.append((char) ('A' + (c - 'A' + 25) % 26));
            } else if (c >= '0' && c <= '9') {
                // shift back by 1, wrap around from '0' to '9'
                decoded.append((char) ('0' + (c - '0' + 9) % 10));
            } else {
                // leave all other characters unchanged
                decoded.append(c);
            }
        }

        return decoded.toString();
    }
}
