import java.util.*;

public class Solution {
    public boolean triplesSumToZero(List<Integer> l) {
        int n = l.size();
        if (n < 3) return false;

        // Convert to array for efficient access and sort
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = l.get(i);
        }
        Arrays.sort(arr);

        // For each first element, use two‑pointer technique on the remaining part
        for (int i = 0; i < n - 2; i++) {
            int left = i + 1;
            int right = n - 1;
            while (left < right) {
                int sum = arr[i] + arr[left] + arr[right];
                if (sum == 0) {
                    return true;          // found a valid triple
                } else if (sum < 0) {
                    left++;               // need a larger sum
                } else {
                    right--;              // need a smaller sum
                }
            }
        }
        return false; // no triple found
    }
}
