import java.util.*;

class Solution {
    public int fib4(int n) {
        // Base cases
        if (n == 0 || n == 1) return 0;
        if (n == 2) return 2;
        if (n == 3) return 0;

        // Use a sliding window of the last four values
        int[] lastFour = {0, 0, 2, 0};

        for (int i = 4; i <= n; i++) {
            int sum = lastFour[0] + lastFour[1] + lastFour[2] + lastFour[3];
            // Shift the window
            lastFour[0] = lastFour[1];
            lastFour[1] = lastFour[2];
            lastFour[2] = lastFour[3];
            lastFour[3] = sum;
        }

        return lastFour[3];
    }
}
