import java.util.*;

class Solution {
    public double median(List<Integer> l) {
        // Create a sorted copy of the input list
        List<Integer> sorted = new ArrayList<>(l);
        Collections.sort(sorted);

        int n = sorted.size();
        if (n == 0) {
            throw new IllegalArgumentException("List must contain at least one element");
        }

        if (n % 2 == 1) { // odd number of elements
            return sorted.get(n / 2);
        } else { // even number of elements
            int mid1 = n / 2 - 1;
            int mid2 = n / 2;
            return (sorted.get(mid1) + sorted.get(mid2)) / 2.0;
        }
    }
}
