public class Solution {
    public int modp(int n, int p) {
        if (p == 1) return 0;          // 2^n mod 1 is always 0
        long result = 1;
        long base = 2 % p;
        int exp = n;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % p;
            }
            base = (base * base) % p;
            exp >>= 1;
        }
        return (int) result;
    }
}
