public class Solution {
    /**
     * Decodes a string that was encoded by shifting each character forward
     * by its index (0‑based) in the alphabet.
     *
     * @param s the encoded string (consisting of lowercase letters)
     * @return the original decoded string
     */
    public String decodeShift(String s) {
        if (s == null || s.isEmpty()) {
            return s;
        }

        char[] chars = s.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            // Shift back by i positions, wrapping around 'a'..'z'
            int shifted = (chars[i] - 'a' - i) % 26;
            if (shifted < 0) {
                shifted += 26;
            }
            chars[i] = (char) ('a' + shifted);
        }
        return new String(chars);
    }
}
