import java.util.List;

class Solution {
    public boolean monotonic(List<Integer> l) {
        if (l == null || l.size() <= 1) {
            return true; // empty or single element lists are trivially monotonic
        }

        boolean increasing = true;
        boolean decreasing = true;

        for (int i = 1; i < l.size(); i++) {
            int prev = l.get(i - 1);
            int curr = l.get(i);

            if (curr > prev) {
                decreasing = false; // cannot be decreasing
            } else if (curr < prev) {
                increasing = false; // cannot be increasing
            }
            // if curr == prev, both flags remain unchanged
        }

        return increasing || decreasing;
    }
}
