import java.util.List;

public class Solution {
    public boolean monotonic(List<Integer> l) {
        if (l == null || l.size() <= 1) {
            return true;
        }

        Integer prev = l.get(0);
        Integer direction = null; // 1 for increasing, -1 for decreasing

        for (int i = 1; i < l.size(); i++) {
            Integer curr = l.get(i);
            if (curr == null) {
                throw new IllegalArgumentException("List contains null element");
            }

            int cmp = curr.compareTo(prev);
            if (cmp != 0) {
                if (direction == null) {
                    direction = cmp > 0 ? 1 : -1;
                } else if (direction * cmp < 0) {
                    return false; // direction changed
                }
            }
            prev = curr;
        }

        return true;
    }
}
