import java.util.*;

class Solution {
    public int largestPrimeFactor(int n) {
        int largest = 1;
        // Check divisibility by 2 first
        while (n % 2 == 0) {
            largest = 2;
            n /= 2;
        }
        // Check odd factors from 3 upwards
        for (int i = 3; i * i <= n; i += 2) {
            while (n % i == 0) {
                largest = i;
                n /= i;
            }
        }
        // If remaining n is a prime greater than 2
        if (n > 1) {
            largest = n;
        }
        return largest;
    }
}
