import java.util.*;

class Solution {
    /**
     * Returns {@code true} if the string {@code brackets} contains a correctly matched
     * sequence of parentheses, otherwise {@code false}.
     *
     * @param brackets a string consisting only of '(' and ')'
     * @return {@code true} if every opening bracket has a corresponding closing bracket
     */
    public boolean correctBracketing(String brackets) {
        int depth = 0;
        for (char b : brackets.toCharArray()) {
            if (b == '(') {
                depth++;
            } else if (b == ')') {
                depth--;
                // If we close more brackets than we have opened, it's invalid
                if (depth < 0) {
                    return false;
                }
            } else {
                // If any other character appears, the input is invalid
                return false;
            }
        }
        // All opened brackets must be closed
        return depth == 0;
    }
}

