import java.util.*;

class Solution {
    public int fibfib(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Base cases
        if (n == 0 || n == 1) {
            return 0;
        }
        if (n == 2) {
            return 1;
        }

        // Use three variables to keep the last three values
        long a = 0; // fibfib(0)
        long b = 0; // fibfib(1)
        long c = 1; // fibfib(2)
        long next = 0;

        for (int i = 3; i <= n; i++) {
            next = a + b + c; // fibfib(i)
            a = b;
            b = c;
            c = next;
        }

        return (int) next; // cast to int as required by the signature
    }
}
