class Solution {
    public int fibfib(int n) {
        if (n < 0) throw new IllegalArgumentException("n must be non‑negative");
        if (n == 0 || n == 1) return 0;
        if (n == 2) return 1;

        int[] dp = new int[n + 1];
        dp[0] = 0;
        dp[1] = 0;
