import java.util.*;

public class Solution {
    public String circularShift(int x, int shift) {
        // Handle negative numbers by preserving the sign
        boolean negative = x < 0;
        String digits = Integer.toString(Math.abs(x));
        int len = digits.length();

        // If shift is greater than the number of digits, return reversed digits
        if (shift > len) {
            digits = new StringBuilder(digits).reverse().toString();
        } else if (shift > 0) {
            // Circular shift to the right by 'shift' positions
            int split = len - shift;
            digits = digits.substring(split) + digits.substring(0, split);
        }
        // Prepend the sign if the original number was negative
        return negative ? "-" + digits : digits;
    }
}
