import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<Integer> pluck(List<Integer> arr) {
        List<Integer> result = new ArrayList<>();
        if (arr == null || arr.isEmpty()) {
            return result;
        }

        int minValue = Integer.MAX_VALUE;
        int minIndex = -1;

        for (int i = 0; i < arr.size(); i++) {
            int val = arr.get(i);
            if (val % 2 == 0) {          // even value
                if (val < minValue) {    // smaller even value found
                    minValue = val;
                    minIndex = i;
                }
            }
        }

        if (minIndex != -1) {            // at least one even value found
            result.add(minValue);
            result.add(minIndex);
        }

        return result;
    }
}
