import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Solution {
    /**
     * Calculates the number of mangoes in a basket.
     *
     * @param s the string describing the number of apples and oranges
     * @param n the total number of fruits in the basket
     * @return the number of mangoes
     */
    public int fruitDistribution(String s, int n) {
        // Extract all integer numbers from the string
        Pattern pattern = Pattern.compile("(\\d+)");
        Matcher matcher = pattern.matcher(s);

        int apples = 0;
        int oranges = 0;
        int count = 0;

        while (matcher.find() && count < 2) {
            int value = Integer.parseInt(matcher.group(1));
            if (count == 0) {
                apples = value;
            } else if (count == 1) {
                oranges = value;
            }
            count++;
        }

        // Compute mangoes
        return n - apples - oranges;
    }
}
