class Solution {
    public int search(List<Integer> lst) {
        // Find the maximum value to size the frequency array
        int maxVal = Collections.max(lst);
        int[] freq = new int[maxVal + 1];

        // Count occurrences of each integer
        for (int val : lst) {
            freq[val] += 1;
        }

        // Find the greatest integer > 0 whose frequency >= its value
        int answer = 0;
        for (int i = 1; i < freq.length; i++) {
            if (freq[i] >= i) {
                answer = i;          // keep the greatest found so far
            }
        }

        // If no such integer was found, return -1
        return answer == 0 ? -1 : answer;
    }
}
