class Solution {
    public List<Integer> strangeSortList(List<Integer> lst) {
        List<Integer> result = new ArrayList<>();
        List<Integer> remaining = new ArrayList<>(lst);
        boolean pickMin = true; // start with the minimum

        while (!remaining.isEmpty()) {
            if (pickMin) {
                int min = Collections.min(remaining);
                result.add(min);
                remaining.remove(Integer.valueOf(min));
            } else {
                int max = Collections.max(remaining);
                result.add(max);
                remaining.remove(Integer.valueOf(max));
            }
            pickMin = !pickMin; // alternate between min and max
        }

        return result;
    }
}
