import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    public List<Integer> strangeSortList(List<Integer> lst) {
        // Create a copy to avoid mutating the original list
        List<Integer> sorted = new ArrayList<>(lst);
        Collections.sort(sorted);

        List<Integer> result = new ArrayList<>(sorted.size());
        int left = 0;
        int right = sorted.size() - 1;

        while (left <= right) {
            // Take the current minimum
            result.add(sorted.get(left));
            left++;

            // If there are still elements left, take the current maximum
            if (left <= right) {
                result.add(sorted.get(right));
                right--;
            }
        }

        return result;
    }
}
