import java.util.List;
import java.util.Objects;

class Solution {
    public boolean willItFly(List<Integer> q, int w) {
        // Check weight constraint
        int sum = 0;
        for (int val : q) {
            sum += val;
        }
        if (sum > w) {
            return false;
        }

        // Check palindromic (balanced) condition
        int i = 0;
        int j = q.size() - 1;
        while (i < j) {
            if (!Objects.equals(q.get(i), q.get(j))) {
                return false;
            }
            i++;
            j--;
        }

        return true;
    }
}
