public class Solution {
    public boolean willItFly(List<Integer> q, int w) {
        if (q == null) {
            return false; // or throw an exception depending on requirements
        }

        int n = q.size();
        long sum = 0; // use long to avoid overflow for large sums

        for (int i = 0; i < n; i++) {
            // Check palindrome property
            if (!q.get(i).equals(q.get(n - 1 - i))) {
                return false;
            }
            sum += q.get(i);
        }

        return sum <= w;
    }
