    public List<Integer> strangeSortList(List<Integer> lst) {
        // Create a mutable copy and sort it in ascending order
        List<Integer> sorted = new ArrayList<>(lst);
        Collections.sort(sorted);

        List<Integer> result = new ArrayList<>(sorted.size());
        int left = 0;
        int right = sorted.size() - 1;

        // Alternate between the smallest and largest remaining elements
        while (left <= right) {
            result.add(sorted.get(left++));          // take the current minimum
            if (left <= right) {
                result.add(sorted.get(right--));     // take the current maximum
            }
        }

        return result;
    }
