import java.util.*;

class Solution {
    // Helper to check primality
    private static boolean isPrime(int n) {
        if (n < 2) return false;
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) return false;
        }
        return true;
    }

    public boolean isMultiplyPrime(int a) {
        if (a < 2) return false;          // no primes can multiply to a < 2

        int count = 0;                    // number of prime factors (with multiplicity)

        // Try all primes up to 100 (a < 100, so this is sufficient)
        for (int p = 2; p <= 100 && a > 1; p++) {
            if (!isPrime(p)) continue;

            while (a % p == 0) {
                count++;
                a /= p;
                if (count > 3) return false; // early exit if more than 3 primes
            }
        }

        // If after division a > 1, it is a prime factor > 100 (unlikely here)
        if (a > 1) count++;

        return count == 3;
    }
}
