public class Solution {

    public boolean isMultiplyPrime(int a) {
        // Negative numbers, 0, 1, and numbers less than 2 cannot be expressed as a product of primes
        if (a <= 1) {
            return false;
        }

        int count = 0;
        int n = a;

        // Factor out 2s
        while (n % 2 == 0) {
            count++;
            n /= 2;
            if (count > 3) return false; // early exit if more than 3 factors
        }

        // Factor out odd primes
        for (int i = 3; i * i <= n; i += 2) {
            while (n % i == 0) {
                count++;
                n /= i;
                if (count > 3) return false; // early exit
            }
        }

        // If n is now greater than 1, it is a prime factor
        if (n > 1) {
            count++;
        }

        return count == 3;
    }
}
