public class Solution {
    public boolean isSimplePower(int x, int n) {
        // 1 is a power of any n > 0 (n^0 = 1)
        if (x == 1) {
            return true;
        }

        // n must be greater than 1 to have meaningful powers
        if (n <= 1) {
            return false;
        }

        long power = 1;
        while (power < x) {
            power *= n;
            if (power == x) {
                return true;
            }
        }
        return false;
    }
}
