import java.math.BigInteger;

public class Solution {
    public boolean isSimplePower(int x, int n) {
        // Handle special bases
        if (n == 1) return x == 1;
        if (n == -1) return x == 1 || x == -1;
        if (n == 0) return x == 0;

        // 0^k (k>0) is 0, 0^0 is undefined – already handled above
        if (x == 1) return true;   // n^0 = 1 for any n != 0
        if (x == 0) return false;  // no non‑zero base yields 0

        BigInteger bigX = BigInteger.valueOf(x);
        BigInteger bigN = BigInteger.valueOf(n);
        BigInteger product = BigInteger.ONE;

        // Multiply until the absolute value of product exceeds that of x
        while (product.abs().compareTo(bigX.abs()) < 0) {
            product = product.multiply(bigN);
            if (product.equals(bigX)) {
                return true;
            }
        }
        return false;
    }
}
