import java.util.*;

class Solution {
    public boolean isSimplePower(int x, int n) {
        // 1 is a power of any positive n (n^0 = 1)
        if (x == 1) return n > 0;

        // For n <= 1 (except the case n == 1 handled above) no other positive power exists
        if (n <= 1) return false;

        long power = 1;
        while (power < x) {
            // Prevent overflow before multiplication
            if (power > Long.MAX_VALUE / n) break;
            power *= n;
        }
        return power == x;
    }
}
