public class Solution {
    public int hexKey(String num) {
        if (num == null || num.isEmpty()) {
            return 0;
        }
        int count = 0;
        for (int i = 0; i < num.length(); i++) {
            char c = num.charAt(i);
            switch (c) {
                case '2':
                case '3':
                case '5':
                case '7':
                case 'B':
                case 'D':
                    count++;
                    break;
                default:
                    // not a prime hex digit
                    break;
            }
        }
        return count;
    }
}
