import java.lang.*;

class Solution {
    public boolean primeLength(String string) {
        if (string == null) {
            return false; // or throw IllegalArgumentException
        }

        int len = string.length();
        if (len <= 1) {
            return false;
        }

        // 2 is the only even prime
        if (len == 2) {
            return true;
        }
        if (len % 2 == 0) {
            return false;
        }

        // Check odd divisors up to sqrt(len)
        int sqrt = (int) Math.sqrt(len);
        for (int i = 3; i <= sqrt; i += 2) {
            if (len % i == 0) {
                return false;
            }
        }
        return true;
    }
}
