public class Solution {
    public int startsOneEnds(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }
        if (n == 1) {
            // Only the number 1 satisfies both start and end with 1
            return 1;
        }
        // Compute 10^(n-2) using long to avoid overflow for moderate n
        long pow10 = 1;
        for (int i = 0; i < n - 2; i++) {
            pow10 *= 10;
        }
        long result = 18L * pow10; // 18 * 10^(n-2)
        return (int) result; // cast to int as required by the method signature
    }
}
