    public String solve(int N) {
        int sum = 0;
        int temp = N;
        while (temp > 0) {
            sum += temp % 10;
            temp /= 10;
        }
        // Handle the case when N is 0
        if (N == 0) {
            sum = 0;
        }
        return Integer.toBinaryString(sum);
    }
}
