import java.util.*;

class Solution {
    public String antiShuffle(String s) {
        // Split on space but keep trailing empty strings
        String[] words = s.split(" ", -1);
        List<String> sortedWords = new ArrayList<>(words.length);

        for (String word : words) {
            char[] chars = word.toCharArray();
            Arrays.sort(chars);          // sort characters by ASCII value
            sortedWords.add(String.copyValueOf(chars));
        }

        // Join the words back together with single spaces
        return String.join(" ", sortedWords);
    }
}
