import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    public List<List<Integer>> getRow(List<List<Integer>> lst, int x) {
        List<List<Integer>> result = new ArrayList<>();

        for (int rowIndex = 0; rowIndex < lst.size(); rowIndex++) {
            List<Integer> row = lst.get(rowIndex);
            if (row == null || row.isEmpty()) {
                continue;
            }

            List<List<Integer>> rowCoords = new ArrayList<>();

            for (int colIndex = 0; colIndex < row.size(); colIndex++) {
                if (row.get(colIndex) == x) {
                    List<Integer> coord = new ArrayList<>(2);
                    coord.add(rowIndex);
                    coord.add(colIndex);
                    rowCoords.add(coord);
                }
            }

            // Sort columns in descending order for this row
            Collections.sort(rowCoords, (a, b) -> Integer.compare(b.get(1), a.get(1)));

            result.addAll(rowCoords);
        }

        return result;
    }
}
