class Solution {
    public List<Integer> sortArray(List<Integer> array) {
        if (array.isEmpty()) {
            return array; // original array is unchanged
        }
        List<Integer> result = new ArrayList<>(array); // make a copy
        int sum = result.get(0) + result.get(result.size() - 1);
        if (sum % 2 == 1) {
            Collections.sort(result); // ascending
        } else {
            result.sort(Collections.reverseOrder()); // descending
        }
        return result;
    }
}
