import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    public List<Integer> sortArray(List<Integer> array) {
        // Return a copy of the original list
        List<Integer> result = new ArrayList<>(array);

        // If the list is empty or has only one element, no sorting is needed
        if (result.size() <= 1) {
            return result;
        }

        // Determine whether to sort ascending or descending
        int sum = result.get(0) + result.get(result.size() - 1);
        if (sum % 2 == 0) {
            // Even sum: sort in descending order
            result.sort(Collections.reverseOrder());
        } else {
            // Odd sum: sort in ascending order
            Collections.sort(result);
        }

        return result;
    }
}
