import java.util.*;

class Solution {
    public Optional<Integer> nextSmallest(List<Integer> lst) {
        if (lst == null) {
            return Optional.empty();
        }

        // Remove duplicates
        Set<Integer> unique = new HashSet<>(lst);

        // Sort the unique values
        List<Integer> sorted = new ArrayList<>(unique);
        Collections.sort(sorted);

        // If there are fewer than 2 distinct values, no second smallest exists
        if (sorted.size() < 2) {
            return Optional.empty();
        }

        // Return the second smallest element
        return Optional.of(sorted.get(1));
    }
}
