public class Solution {
    public Optional<Integer> nextSmallest(List<Integer> lst) {
        if (lst == null || lst.isEmpty()) {
            return Optional.empty();
        }

        // Remove duplicates and sort the remaining values
        Set<Integer> unique = new HashSet<>(lst);
        if (unique.size() < 2) {
            return Optional.empty();
        }

        List<Integer> sorted = new ArrayList<>(unique);
        Collections.sort(sorted);

        // The second element in the sorted list is the 2nd smallest distinct value
        return Optional.of(sorted.get(1));
    }
}
