class Solution {
    public int skjkasdkd(List<Integer> lst) {
        int maxPrime = -1;

        for (int num : lst) {
            if (num > 1 && isPrime(num) && num > maxPrime) {
                maxPrime = num;
            }
        }

        if (maxPrime == -1) {
            return 0; // no prime found
        }

        int sum = 0;
        int temp = maxPrime;
        while (temp > 0) {
            sum += temp % 10;
            temp /= 10;
        }
        return sum;
    }

    private boolean isPrime(int n) {
        if (n <= 1) return false;
        if (n == 2) return true;
        if (n % 2 == 0) return false;

        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) return false;
        }
        return true;
    }
}
