import java.util.Map;

public class Solution {
    public boolean checkDictCase(Map<Object, Object> dict) {
        if (dict == null || dict.isEmpty()) {
            return false;
        }

        boolean lowerCaseSeen = false;
        boolean upperCaseSeen = false;

        for (Object keyObj : dict.keySet()) {
            if (!(keyObj instanceof String)) {
                return false; // non‑string key
            }
            String key = (String) keyObj;

            // Empty string is considered both lower and upper case
            if (key.isEmpty()) {
                lowerCaseSeen = true;
                continue;
            }

            boolean isLower = key.equals(key.toLowerCase());
            boolean isUpper = key.equals(key.toUpperCase());

            if (isLower && !isUpper) {
                lowerCaseSeen = true;
            } else if (isUpper && !isLower) {
                upperCaseSeen = true;
            } else {
                // Mixed case or non‑alphabetic characters that change case
                return false;
            }

            // Early exit if both cases are seen
            if (lowerCaseSeen && upperCaseSeen) {
                return false;
            }
        }

        // If we reached here, all keys are either all lower or all upper
        return lowerCaseSeen || upperCaseSeen;
    }
}
