public class Solution {
    public int countUpper(String value) {
        double d = Double.parseDouble(value);
        int floor = (int) Math.floor(d);
        int ceil  = (int) Math.ceil(d);

        double diffFloor = Math.abs(d - floor);
        double diffCeil  = Math.abs(ceil - d);

        if (diffFloor < diffCeil) {
            return floor;
        } else if (diffCeil < diffFloor) {
            return ceil;
        } else { // tie – round away from zero
            return Math.abs(floor) > Math.abs(ceil) ? floor : ceil;
        }
    }
}
