public class Solution {
    public int chooseNum(int x, int y) {
        // If the range is invalid, return -1
        if (x > y) {
            return -1;
        }

        // Find the largest even number <= y
        int largestEven = (y % 2 == 0) ? y : y - 1;

        // If that even number is within the range, return it; otherwise, no even number exists
        return (largestEven >= x) ? largestEven : -1;
    }
