public class Solution {
    public List<Integer> uniqueDigits(List<Integer> x) {
        List<Integer> result = new ArrayList<>();
        for (Integer num : x) {
            if (num == null) continue; // skip nulls if any
            if (hasOnlyOddDigits(num)) {
                result.add(num);
            }
        }
        Collections.sort(result);
        return result;
    }

    private boolean hasOnlyOddDigits(int num) {
        int n = Math.abs(num); // just in case, though numbers are positive
        if (n == 0) return false; // 0 contains an even digit
        while (n > 0) {
            int digit = n % 10;
            if (digit % 2 == 0) { // even digit found
                return false;
            }
            n /= 10;
        }
        return true;
    }
}
