    public List<Integer> f(int n) {
        List<Integer> result = new ArrayList<>(n);
        for (int i = 1; i <= n; i++) {
            if (i % 2 == 0) {          // even index – factorial
                int fact = 1;
                for (int j = 1; j <= i; j++) {
                    fact *= j;
