class Solution {
    public int countNums(List<Integer> arr) {
        int count = 0;
        for (int n : arr) {
            boolean negative = n < 0;
            int abs = Math.abs(n);
            String s = String.valueOf(abs);
            int sum = 0;
            for (int i = 0; i < s.length(); i++) {
                int digit = s.charAt(i) - '0';
                if (i == 0 && negative) {
                    sum -= digit;          // first digit is negative
                } else {
                    sum += digit;
                }
            }
            if (sum > 0) {
                count++;
            }
        }
        return count;
    }
}
