import java.util.*;

class Solution {
    public boolean moveOneBall(List<Integer> arr) {
        int n = arr.size();
        if (n == 0) {
            return true;
        }

        int descentCount = 0;
        for (int i = 0; i < n; i++) {
            int current = arr.get(i);
            int next = arr.get((i + 1) % n);
            if (current > next) {
                descentCount++;
            }
        }

        if (descentCount == 0) {
            return true; // already sorted
        }
        if (descentCount == 1) {
            // ensure the wrap‑around part is also in order
            return arr.get(n - 1) <= arr.get(0);
        }
        return false; // more than one descent, cannot be sorted by rotation
    }
}
