import java.util.*;

class Solution {
    public boolean moveOneBall(List<Integer> arr) {
        // Empty array is considered sorted
        if (arr.isEmpty()) {
            return true;
        }

        // Create a sorted copy of the original list
        List<Integer> sorted = new ArrayList<>(arr);
        Collections.sort(sorted);

        // Find the index of the minimum element in the original list
        int minIndex = 0;
        for (int i = 1; i < arr.size(); i++) {
            if (arr.get(i) < arr.get(minIndex)) {
                minIndex = i;
            }
        }

        // Rotate the original list so that the minimum element is first
        List<Integer> rotated = new ArrayList<>(arr.subList(minIndex, arr.size()));
        rotated.addAll(arr.subList(0, minIndex));

        // Compare the rotated list with the sorted list
        for (int i = 0; i < arr.size(); i++) {
            if (!rotated.get(i).equals(sorted.get(i))) {
                return false;
            }
        }
        return true;
    }
}
