import java.util.List;

public class Solution {
    /**
     * Determines whether the given list can be sorted in non‑decreasing order
     * by performing any number of right shift operations.
     *
     * @param arr the list of unique integers
     * @return true if a sorted array can be obtained by right shifts, false otherwise
     */
    public boolean moveOneBall(List<Integer> arr) {
        int n = arr.size();
        if (n <= 1) {
            // Empty or single element list is already sorted
            return true;
        }

        int dropCount = 0;
        for (int i = 0; i < n; i++) {
            int current = arr.get(i);
            int next = arr.get((i + 1) % n);
            if (current > next) {
                dropCount++;
                if (dropCount > 1) {
                    return false; // More than one drop means impossible
                }
            }
        }
        return true; // 0 or 1 drop indicates a rotation of a sorted array
    }
}
