import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Solution {

    public List<Object> reverseDelete(String s, String c) {
        // Build a set of characters to delete
        Set<Character> deleteSet = new HashSet<>();
        for (char ch : c.toCharArray()) {
            deleteSet.add(ch);
        }

        // Build the resulting string after deletion
        StringBuilder sb = new StringBuilder();
        for (char ch : s.toCharArray()) {
            if (!deleteSet.contains(ch)) {
                sb.append(ch);
            }
        }
        String result = sb.toString();

        // Check if the result is a palindrome
        boolean isPalindrome = true;
        int left = 0;
        int right = result.length() - 1;
        while (left < right) {
            if (result.charAt(left) != result.charAt(right)) {
                isPalindrome = false;
                break;
            }
            left++;
            right--;
        }

        // Prepare the return tuple
        List<Object> output = new ArrayList<>();
        output.add(result);
        output.add(isPalindrome);
        return output;
    }
}
