import java.util.List;

public class Solution {
    public int minSubArraySum(List<Integer> nums) {
        if (nums == null || nums.isEmpty()) {
            throw new IllegalArgumentException("Input list must be non-empty");
        }

        int minEnding = nums.get(0);
        int minSoFar = nums.get(0);

        for (int i = 1; i < nums.size(); i++) {
            int val = nums.get(i);
            minEnding = Math.min(val, minEnding + val);
            minSoFar = Math.min(minSoFar, minEnding);
        }

        return minSoFar;
    }
}
