import java.util.List;

class Solution {
    public int maxFill(List<List<Integer>> grid, int capacity) {
        int totalDrops = 0;
        for (List<Integer> row : grid) {
            int waterUnits = 0;
            for (int val : row) {
                waterUnits += val;          // val is 0 or 1
            }
            if (waterUnits > 0) {
                totalDrops += (waterUnits + capacity - 1) / capacity; // ceil division
            }
        }
        return totalDrops;
    }
}
