import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Integer> sortArray(List<Integer> arr) {
        List<Integer> result = new ArrayList<>(arr);
        result.sort((a, b) -> {
            // Handle negative numbers first
            if (a < 0 && b < 0) {
                return Integer.compare(a, b);
            } else if (a < 0) {
                return -1; // negative numbers come before non‑negative
            } else if (b < 0) {
                return 1;
            }

            // Both numbers are non‑negative: sort by number of 1s, then by value
            int onesA = Integer.bitCount(a);
            int onesB = Integer.bitCount(b);
            if (onesA != onesB) {
                return Integer.compare(onesA, onesB);
            }
            return Integer.compare(a, b);
        });
        return result;
    }
}
