import java.util.List;

class Solution {
    public List<Integer> maximum(List<Integer> arr, int k) {
        if (k == 0) {
            return Collections.emptyList();
        }

        // Create a mutable copy and sort it in ascending order
        List<Integer> sorted = new ArrayList<>(arr);
        Collections.sort(sorted);

        // Take the last k elements (the largest k numbers)
        int start = sorted.size() - k;
        List<Integer> result = new ArrayList<>(sorted.subList(start, sorted.size()));

        return result;
    }
}
