            } else if (c == ')') {
                balance--;
            } else {
                // Invalid character; according to problem statement this shouldn't happen
                return false;
            }
            if (balance < 0) {
                return false; // more closing than opening at some prefix
            }
        }
        return balance == 0; // all parentheses matched
    }
}
