public class Solution {
    public List<Integer> maximum(List<Integer> arr, int k) {
        if (k == 0) {
            return new ArrayList<>();
        }

        // Make a copy to avoid modifying the original list
        List<Integer> copy = new ArrayList<>(arr);

        // Sort in descending order to get the largest elements first
        copy.sort(Collections.reverseOrder());

        // Take the first k elements (the largest k numbers)
        List<Integer> result = new ArrayList<>(copy.subList(0, k));

        // Sort the result in ascending order as required
        result.sort(Integer::compareTo);

        return result;
    }
}
