import java.util.*;

class Solution {
    public List<Integer> getOddCollatz(int n) {
        List<Integer> odds = new ArrayList<>();
        long current = n;

        // Add the starting number if it is odd
        if (current % 2 == 1) {
            odds.add((int) current);
        }

        // Generate the Collatz sequence until we reach 1
        while (current > 1) {
            if (current % 2 == 0) {
                current /= 2;
            } else {
                current = 3 * current + 1;
            }

            // Record odd numbers
            if (current % 2 == 1) {
                odds.add((int) current);
            }
        }

        // Sort the collected odd numbers in ascending order
        Collections.sort(odds);
        return odds;
    }
}
