import java.util.*;

class Solution {
    public boolean validDate(String date) {
        // 1. Check for null or empty string
        if (date == null || date.isEmpty()) {
            return false;
        }

        // 2. Split the string by hyphen and verify the format mm-dd-yyyy
        String[] parts = date.split("-");
        if (parts.length != 3) {
            return false;
        }

        // 3. Ensure each part has the correct length
        if (parts[0].length() != 2 || parts[1].length() != 2 || parts[2].length() != 4) {
            return false;
        }

        try {
            int month = Integer.parseInt(parts[0]); // mm
            int day   = Integer.parseInt(parts[1]); // dd
            int year  = Integer.parseInt(parts[2]); // yyyy (value not used for validation)

            // 4. Validate month range
            if (month < 1 || month > 12) {
                return false;
            }

            // 5. Validate day range based on month
            if (day < 1) {
                return false;
            }

            switch (month) {
                case 1: case 3: case 5: case 7: case 8: case 10: case 12:
                    if (day > 31) return false;
                    break;
                case 4: case 6: case 9: case 11:
                    if (day > 30) return false;
                    break;
                case 2:
                    if (day > 29) return false; // no leap‑year check required
                    break;
            }

            return true;
        } catch (NumberFormatException e) {
            // Non‑numeric parts
            return false;
        }
    }
}
