import java.util.regex.Pattern;

public class Solution {

    public boolean validDate(String date) {
        // Rule 1: date string must not be empty
        if (date == null || date.isEmpty()) {
            return false;
        }

        // Rule 4: must match mm-dd-yyyy format (two digits, hyphen, two digits, hyphen, four digits)
        Pattern pattern = Pattern.compile("^(\\d{2})-(\\d{2})-(\\d{4})$");
        Matcher matcher = pattern.matcher(date);
        if (!matcher.matches()) {
            return false;
        }

        int month = Integer.parseInt(matcher.group(1));
        int day   = Integer.parseInt(matcher.group(2));
        // year is matcher.group(3) but not needed for validation

        // Rule 3: month must be between 1 and 12
        if (month < 1 || month > 12) {
            return false;
        }

        // Rule 2: day limits per month
        switch (month) {
            case 1: case 3: case 5: case 7: case 8: case 10: case 12:
                if (day < 1 || day > 31) return false;
                break;
            case 4: case 6: case 9: case 11:
                if (day < 1 || day > 30) return false;
                break;
            case 2:
                if (day < 1 || day > 29) return false;
                break;
            default:
                // This case is unreachable due to earlier month check
                return false;
        }

        return true;
    }
