import java.util.*;

public class Solution {
    public boolean validDate(String date) {
        if (date == null) return false;
        date = date.strip();
        if (date.isEmpty()) return false;

        String[] parts = date.split("-");
        if (parts.length != 3) return false;

        String m = parts[0];
        String d = parts[1];
        String y = parts[2];

        // Remove leading zeros
        while (!m.isEmpty() && m.charAt(0) == '0') m = m.substring(1);
        while (!d.isEmpty() && d.charAt(0) == '0') d = d.substring(1);
        while (!y.isEmpty() && y.charAt(0) == '0') y = y.substring(1);

        try {
            int month = Integer.parseInt(m);
            int day   = Integer.parseInt(d);
            int year  = Integer.parseInt(y);

            if (month < 1 || month > 12) return false;

            if ((month == 1 || month == 3 || month == 5 || month == 7 ||
                 month == 8 || month == 10 || month == 12) &&
                (day < 1 || day > 31)) return false;

            if ((month == 4 || month == 6 || month == 9 || month == 11) &&
                (day < 1 || day > 30)) return false;

            if (month == 2 && (day < 1 || day > 29)) return false;

            return true;
        } catch (Exception e) {
            return false;
        }
    }
}
