import java.util.*;

class Solution {
    public Object splitWords(String txt) {
        if (txt == null) {
            return null;
        }

        // Split on whitespace if any
        if (txt.contains(" ")) {
            // Trim to avoid leading/trailing empty tokens
            String[] parts = txt.trim().split("\\s+");
            return Arrays.asList(parts);
        }

        // Split on commas if any
        if (txt.contains(",")) {
            String[] parts = txt.split(",");
            return Arrays.asList(parts);
        }

        // Count lower‑case letters with odd alphabetic order
        int count = 0;
        for (char c : txt.toCharArray()) {
            if (c >= 'a' && c <= 'z' && ((c - 'a') % 2 == 1)) {
                count++;
            }
        }
        return count;
    }
}
