import java.util.List;

class Solution {
    public boolean isSorted(List<Integer> lst) {
        if (lst == null || lst.size() <= 1) {
            return true;
        }

        int prev = lst.get(0);
        int duplicateCount = 1; // count of the current value

        for (int i = 1; i < lst.size(); i++) {
            int curr = lst.get(i);

            // Check ascending order
            if (curr < prev) {
                return false;
            }

            // Count duplicates
            if (curr == prev) {
                duplicateCount++;
                if (duplicateCount > 2) {
                    return false; // more than two occurrences of the same number
                }
            } else {
                duplicateCount = 1; // reset for new number
                prev = curr;
            }
        }

        return true;
    }
}
