import java.util.List;
import java.util.Optional;

public class Solution {
    public Optional<Integer> prodSigns(List<Integer> arr) {
        if (arr.isEmpty()) {
            return Optional.empty();
        }

        // If any element is zero, the product of signs is zero
        if (arr.contains(0)) {
            return Optional.of(0);
        }

        // Sum of absolute values
        int sumAbs = arr.stream()
                        .mapToInt(Math::abs)
                        .sum();

        // Product of signs: 1 if even number of negatives, -1 otherwise
        int signProduct = (int) (arr.stream()
                                    .filter(n -> n < 0)
                                    .count() % 2 == 0 ? 1 : -1);

        return Optional.of(signProduct * sumAbs);
    }
}
