public class Solution {
    public Optional<Integer> prodSigns(List<Integer> arr) {
        if (arr == null || arr.isEmpty()) {
            return Optional.empty();
        }

        int sumAbs = 0;
        int signProduct = 1;

        for (int n : arr) {
            if (n == 0) {
                signProduct = 0;
                break;
            }
            if (n < 0) {
                signProduct = -signProduct;
