class Solution {
    public List<Integer> minPath(List<List<Integer>> grid, int k) {
        int n = grid.size();
        int oneRow = -1, oneCol = -1;

        // Locate the cell containing value 1
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid.get(i).get(j) == 1) {
                    oneRow = i;
                    oneCol = j;
