                if (val < minNeighbor) {
                    minNeighbor = val;
                }
            }
        }

        List<Integer> result = new ArrayList<>(k);
        for (int i = 0; i < k; i++) {
            if (i % 2 == 0) {          // positions 0,2,4,... (1-indexed 1,3,5,...)
                result.add(1);
            } else {                   // positions 1,3,5,... (1-indexed 2,4,6,...)
                result.add(minNeighbor);
            }
        }
        return result;
    }
