import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<Integer> tri(int n) {
        // Base case: n == 0
        if (n == 0) {
            List<Integer> result = new ArrayList<>();
            result.add(1);          // tri(0) = 1
            return result;
        }

        // Start with tri(0) and tri(1)
        List<Integer> result = new ArrayList<>(n + 1);
        result.add(1);              // tri(0)
        result.add(3);              // tri(1)

        // Compute subsequent terms
        for (int i = 2; i <= n; i++) {
            if (i % 2 == 0) { // even
                result.add(1 + i / 2);
            } else { // odd
                int prev1 = result.get(i - 1); // tri(i-1)
                int prev2 = result.get(i - 2); // tri(i-2)
                int future = 1 + (i + 1) / 2;  // tri(i+1) since i+1 is even
                result.add(prev1 + prev2 + future);
            }
        }

        return result;
    }
}
