import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<Integer> tri(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // The list will contain the first n+1 terms: tri(0) … tri(n)
        List<Integer> result = new ArrayList<>(n + 1);

        // Base cases
        result.add(1);                 // tri(0)
        if (n == 0) {
            return result;
        }
        result.add(3);                 // tri(1)

        // Compute remaining terms
        for (int i = 2; i <= n; i++) {
            int value;
            if (i % 2 == 0) {          // even index
                value = 1 + i / 2;
            } else {                   // odd index
                // tri(i) = tri(i-1) + tri(i-2) + tri(i+1)
                // tri(i+1) is even, so tri(i+1) = 1 + (i+1)/2
                value = result.get(i - 1) + result.get(i - 2) + 1 + (i + 1) / 2;
            }
            result.add(value);
        }

        return result;
    }
}
