import java.util.*;

public class Solution {
    public List<Integer> minPath(List<List<Integer>> grid, int k) {
        int N = grid.size();
        int total = N * N;
        int[][] arr = new int[N][N];
        for (int r = 0; r < N; r++) {
            for (int c = 0; c < N; c++) {
                arr[r][c] = grid.get(r).get(c);
            }
        }

        // prev[t][cell] = previous cell index at step t-1 that gives minimal path
        int[][] prev = new int[k + 1][total];
        boolean[][] reachable = new boolean[k + 1][total];
        for (int i = 0; i <= k; i++) {
            Arrays.fill(prev[i], -2); // -2 means unreachable
        }

        // step 1: any cell is reachable
        for (int i = 0; i < total; i++) {
            reachable[1][i] = true;
            prev[1][i] = -1; // start
        }

        // Precompute neighbor indices for each cell
        int[][] neighbors = new int[total][4];
        int[] neighCnt = new int[total];
        for (int r = 0; r < N; r++) {
            for (int c = 0; c < N; c++) {
                int idx = r * N + c;
                int cnt = 0;
                if (r > 0) neighbors[idx][cnt++] = (r - 1) * N + c;
                if (r < N - 1) neighbors[idx][cnt++] = (r + 1) * N + c;
                if (c > 0) neighbors[idx][cnt++] = r * N + (c - 1);
                if (c < N - 1) neighbors[idx][cnt++] = r * N + (c + 1);
                neighCnt[idx] = cnt;
            }
        }

        // DP for steps 2..k
        for (int t = 2; t <= k; t++) {
            for (int i = 0; i < total; i++) {
                int bestPrev = -1;
                int cnt = neighCnt[i];
                for (int nIdx = 0; nIdx < cnt; nIdx++) {
                    int j = neighbors[i][nIdx];
                    if (!reachable[t - 1][j]) continue;
                    if (bestPrev == -1) {
                        bestPrev = j;
                    } else {
                        int cmp = compareSeq(t - 1, j, bestPrev, prev, arr, N);
                        if (cmp < 0) {
                            bestPrev = j;
                        }
                    }
                }
                if (bestPrev != -1) {
                    reachable[t][i] = true;
                    prev[t][i] = bestPrev;
                }
            }
        }

        // Find best cell at step k
        int bestCell = -1;
        for (int i = 0; i < total; i++) {
            if (!reachable[k][i]) continue;
            if (bestCell == -1) {
                bestCell = i;
            } else {
                int cmp = compareSeq(k, i, bestCell, prev, arr, N);
                if (cmp < 0) {
                    bestCell = i;
                }
            }
        }

        // Reconstruct path
        List<Integer> result = new ArrayList<>(k);
        int cell = bestCell;
        for (int s = k; s >= 1; s--) {
            int r = cell / N;
            int c = cell % N;
            result.add(arr[r][c]);
            if (s > 1) {
                cell = prev[s][cell];
            }
        }
        Collections.reverse(result);
        return result;
    }

    // Compare two sequences of length t ending at cell1 and cell2
    private int compareSeq(int t, int cell1, int cell2, int[][] prev, int[][] arr, int N) {
        int s = t;
        int c1 = cell1;
        int c2 = cell2;
        while (s >= 1) {
            int r1 = c1 / N, col1 = c1 % N;
            int r2 = c2 / N, col2 = c2 % N;
            int val1 = arr[r1][col1];
            int val2 = arr[r2][col2];
            if (val1 != val2) {
                return val1 < val2 ? -1 : 1;
            }
            if (s == 1) break;
            c1 = prev[s][c1];
            c2 = prev[s][c2];
            s--;
        }
        return 0; // equal
    }
}
