import java.util.List;

public class Solution {
    public String intersection(List<Integer> interval1, List<Integer> interval2) {
        // Extract start and end points
        int start1 = interval1.get(0);
        int end1   = interval1.get(1);
        int start2 = interval2.get(0);
        int end2   = interval2.get(1);

        // Compute intersection bounds
        int interStart = Math.max(start1, start2);
        int interEnd   = Math.min(end1, end2);

        // No intersection
        if (interStart > interEnd) {
            return "NO";
        }

        // Length of intersection (closed interval)
        int length = interEnd - interStart + 1;

        // Check if length is prime
        if (isPrime(length)) {
            return "YES";
        } else {
            return "NO";
        }
    }

    // Helper method to test primality
    private boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

