import java.util.*;

class Solution {
    public boolean isNested(String string) {
        int n = string.length();
        if (n < 4) return false; // cannot contain a nested pair

        // suffixClose[i] = number of ']' characters from index i to the end
        int[] suffixClose = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            suffixClose[i] = suffixClose[i + 1] + (string.charAt(i) == ']' ? 1 : 0);
        }

        int openBefore = 0; // number of '[' seen so far
        for (int i = 0; i < n; i++) {
            char c = string.charAt(i);
            if (c == '[') {
                if (openBefore > 0 && suffixClose[i + 1] >= 2) {
                    return true; // found a nested subsequence
                }
                openBefore++;
            }
        }
        return false;
    }
}
