public class Solution {
    public boolean isNested(String s) {
        if (s == null || s.length() < 4) return false;

        // Pattern we look for: "[[ ]]"
        char[] pattern = {'[', '[', ']', ']'};
        boolean[] dp = new boolean[5];
        dp[0] = true; // empty prefix always matched

        for (char c : s.toCharArray()) {
            // Update dp from the end to avoid overwriting needed values
            for (int i = 3; i >= 0; i--) {
                if (c == pattern[i] && dp[i]) {
                    dp[i + 1] = true;
                }
            }
        }
        return dp[4];
    }
}
