    public boolean checkIfLastCharIsALetter(String txt) {
        if (txt == null || txt.isEmpty()) {
            return false;
        }
        // Split on space, keeping trailing empty strings
        String[] words = txt.split(" ", -1);
        String last = words[words.length - 1];
