public class Solution {
    public boolean isNested(String string) {
        int firstOpen = -1, secondOpen = -1;
        int firstClose = -1, secondClose = -1;

        for (int i = 0; i < string.length(); i++) {
            char c = string.charAt(i);
            if (c == '[') {
                if (firstOpen == -1) {
                    firstOpen = i;
                } else if (secondOpen == -1) {
                    secondOpen = i;
                }
            } else if (c == ']') {
                if (secondOpen != -1 && firstClose == -1) {
                    firstClose = i;          // close for the second open
                } else if (firstClose != -1 && secondClose == -1) {
                    secondClose = i;         // close for the first open
                }
            }
        }
        return secondClose != -1;
    }
}
