public class Solution {
    public boolean checkIfLastCharIsALetter(String txt) {
        if (txt == null || txt.isEmpty()) {
            return false;
        }

        int len = txt.length();
        char lastChar = txt.charAt(len - 1);

        // Must be a letter
        if (!Character.isLetter(lastChar)) {
            return false;
        }

        // If it's the only character, it's a single-letter word
        if (len == 1) {
            return true;
        }

        // The preceding character must be a space to ensure it's not part of a word
        char prevChar = txt.charAt(len - 2);
        return prevChar == ' ';
    }
}
