public class Solution {
    public List<Optional<Integer>> largestSmallestIntegers(List<Integer> lst) {
        Integer largestNegative = null;
        Integer smallestPositive = null;

        for (Integer num : lst) {
            if (num == null) continue; // skip nulls if any

            if (num < 0) {
                if (largestNegative == null || num > largestNegative) {
                    largestNegative = num;
                }
            } else if (num > 0) {
                if (smallestPositive == null || num < smallestPositive) {
                    smallestPositive = num;
                }
            }
        }

        List<Optional<Integer>> result = new ArrayList<>(2);
        result.add(Optional.ofNullable(largestNegative));
        result.add(Optional.ofNullable(smallestPositive));
        return result;
    }
}
