public class Solution {
    public long specialFactorial(int n) {
        long fact = 1;          // current factorial i!
        long special = 1;       // product of all factorials up to n!

        for (int i = 1; i <= n; i++) {
            fact *= i;          // compute i!
            special *= fact;    // multiply into the special factorial
        }

        return special;
