public class Solution {
    /**
     * Computes the Brazilian factorial of n:
     * brazilian_factorial(n) = n! * (n-1)! * ... * 1!
     *
     * @param n the input integer (n > 0)
     * @return the special factorial as a long
     */
    public long specialFactorial(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be greater than 0");
        }

        long result = 1L;
        long factorial = 1L;

        for (int i = 1; i <= n; i++) {
            factorial *= i;   // compute i!
            result *= factorial; // multiply into the product
        }

        return result;
    }
}
