import java.util.*;

class Solution {
    public String filenameCheck(String file_name) {
        // Allowed suffixes
        List<String> allowedSuffixes = Arrays.asList("txt", "exe", "dll");

        // Split on dot; must result in exactly two parts
        String[] parts = file_name.split("\\.");
        if (parts.length != 2) {
            return "No";
        }

        String namePart = parts[0];
        String suffixPart = parts[1];

        // Name part must not be empty and must start with a Latin letter
        if (namePart.isEmpty() || !Character.isLetter(namePart.charAt(0))) {
            return "No";
        }

        // Suffix part must be one of the allowed values
        if (!allowedSuffixes.contains(suffixPart)) {
            return "No";
        }

        // Count digits in the name part; must not exceed 3
        long digitCount = namePart.chars()
                                  .filter(Character::isDigit)
                                  .count();
        if (digitCount > 3) {
            return "No";
        }

        return "Yes";
    }
}
