public class Solution {
    public String filenameCheck(String file_name) {
        // Condition 1: No more than three digits in the entire file name
        int digitCount = 0;
        for (int i = 0; i < file_name.length(); i++) {
            if (Character.isDigit(file_name.charAt(i))) {
                digitCount++;
                if (digitCount > 3) {
                    return "No";
                }
            }
        }

        // Condition 2: Exactly one dot '.'
        int firstDot = file_name.indexOf('.');
        int lastDot = file_name.lastIndexOf('.');
        if (firstDot == -1 || firstDot != lastDot) {
            return "No";
        }

        // Split into name and extension
        String namePart = file_name.substring(0, firstDot);
        String extPart = file_name.substring(firstDot + 1);

        // Condition 3: Name part not empty and starts with a Latin letter
        if (namePart.isEmpty() || !Character.isLetter(namePart.charAt(0))) {
            return "No";
        }

        // Condition 4: Extension must be one of the allowed types
        if (!extPart.equals("txt") && !extPart.equals("exe") && !extPart.equals("dll")) {
            return "No";
        }

        return "Yes";
    }
}
