import java.math.BigInteger;

class Solution {
    public boolean simplify(String x, String n) {
        // Split the fractions into numerator and denominator
        String[] a = x.split("/");
        String[] b = n.split("/");

        // Parse the parts as BigIntegers to avoid overflow
        BigInteger numX = new BigInteger(a[0]);
        BigInteger denX = new BigInteger(a[1]);
        BigInteger numN = new BigInteger(b[0]);
        BigInteger denN = new BigInteger(b[1]);

        // Compute the product of the two fractions
        BigInteger numerator   = numX.multiply(numN);
        BigInteger denominator = denX.multiply(denN);

        // The product is a whole number if the numerator is divisible by the denominator
        return numerator.mod(denominator).equals(BigInteger.ZERO);
    }
}
