import java.util.*;

class Solution {
    public List<Integer> orderByPoints(List<Integer> nums) {
        // Pair holds the original value and its index
        class Pair {
            int value;
            int index;
            int digitSum;

            Pair(int value, int index) {
                this.value = value;
                this.index = index;
                this.digitSum = digitSum(value);
            }
        }

        // Compute sum of digits of the absolute value
        int digitSum(int n) {
            int sum = 0;
            int m = Math.abs(n);
            if (m == 0) return 0;
            while (m > 0) {
                sum += m % 10;
                m /= 10;
            }
            return sum;
        }

        List<Pair> pairs = new ArrayList<>();
        for (int i = 0; i < nums.size(); i++) {
            pairs.add(new Pair(nums.get(i), i));
        }

        pairs.sort((p1, p2) -> {
            int cmp = Integer.compare(p1.digitSum, p2.digitSum);
            if (cmp != 0) {
                return cmp; // ascending by digit sum
            }
            // descending by original index when sums are equal
            return Integer.compare(p2.index, p1.index);
        });

        List<Integer> result = new ArrayList<>(nums.size());
        for (Pair p : pairs) {
            result.add(p.value);
        }
        return result;
    }
}
