import java.util.*;

public class Solution {
    public List<Integer> orderByPoints(List<Integer> nums) {
        // Pair each number with its original index
        List<IndexedValue> paired = new ArrayList<>(nums.size());
        for (int i = 0; i < nums.size(); i++) {
            paired.add(new IndexedValue(nums.get(i), i));
        }

        // Sort by digit sum, then by original index to keep stability
        paired.sort((a, b) -> {
            int sumA = digitSum(a.value);
            int sumB = digitSum(b.value);
            if (sumA != sumB) {
                return Integer.compare(sumA, sumB);
            }
            return Integer.compare(a.index, b.index);
        });

        // Extract sorted values
