class Solution {
    public String fixSpaces(String text) {
        StringBuilder sb = new StringBuilder();
        int spaceRun = 0; // number of consecutive spaces seen so far

        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c == ' ') {
                spaceRun++;          // accumulate space run
            } else {
                // flush any pending space run
                if (spaceRun > 0) {
                    if (spaceRun > 2) {
                        sb.append('-');
                    } else {
                        sb.append("_".repeat(spaceRun));
                    }
                    spaceRun = 0;
                }
                sb.append(c); // append the non‑space character
            }
        }

        // flush any trailing space run
        if (spaceRun > 0) {
            if (spaceRun > 2) {
                sb.append('-');
            } else {
                sb.append("_".repeat(spaceRun));
            }
        }

        return sb.toString();
    }
}
