class Solution {
    public int getMaxTriples(int n) {
        // Count of indices i (1‑based) such that i % 3 == 2
        long count0 = (n + 1L) / 3L;          // indices 2,5,8,...
        long count1 = n - count0;             // remaining indices

        long triples0 = choose3(count0);
        long triples1 = choose3(count1);

        long result = triples0 + triples1;
        return (int) result; // fits in int for typical constraints
    }

    private long choose3(long x) {
        if (x < 3) return 0;
        return x * (x - 1) * (x - 2) / 6;
    }
}
