import java.util.TreeSet;

public class Solution {
    public List<Integer> getOddCollatz(int n) {
        TreeSet<Integer> oddNumbers = new TreeSet<>();
        long current = n;

        while (true) {
            if (current % 2 == 1) {
                oddNumbers.add((int) current);
            }
            if (current == 1) {
                break;
            }
            if (current % 2 == 0) {
                current /= 2;
            } else {
                current = 3 * current + 1;
            }
        }

        return new ArrayList<>(oddNumbers);
    }
}
