import java.util.*;

class Solution {
    public int getMaxTriples(int n) {
        // Count of indices i (1‑based) with i % 3 == 2  →  a[i] % 3 == 0
        int c0 = (n + 1) / 3;          // floor((n+1)/3)
        int c1 = n - c0;               // remaining indices have a[i] % 3 == 1

        long triples = 0L;

        // Triples where all three residues are 0
        if (c0 >= 3) {
            triples += (long)c0 * (c0 - 1) * (c0 - 2) / 6;
        }

        // Triples where all three residues are 1
        if (c1 >= 3) {
            triples += (long)c1 * (c1 - 1) * (c1 - 2) / 6;
        }

        // No other residue (2) exists, so no mixed‑residue triples are possible.

        return (int)triples;
    }
}
