import java.util.*;

public class Solution {
    private static final String[] PLANETS = {
        "Mercury", "Venus", "Earth", "Mars",
        "Jupiter", "Saturn", "Uranus", "Neptune"
    };

    public List<String> bf(String planet1, String planet2) {
        int index1 = indexOfPlanet(planet1);
        int index2 = indexOfPlanet(planet2);

        if (index1 == -1 || index2 == -1) {
            return Collections.emptyList();
        }

        int start = Math.min(index1, index2) + 1;
        int end   = Math.max(index1, index2) - 1;

        if (start > end) {
            return Collections.emptyList();
        }

        List<String> result = new ArrayList<>(end - start + 1);
        for (int i = start; i <= end; i++) {
            result.add(PLANETS[i]);
        }
        return result;
    }

    private int indexOfPlanet(String planet) {
        for (int i = 0; i < PLANETS.length; i++) {
            if (PLANETS[i].equalsIgnoreCase(planet)) {
                return i;
            }
        }
        return -1;
    }
}
