class Solution {
    public List<String> listSort(List<String> lst) {
        // Filter out strings with odd lengths
        List<String> filtered = new ArrayList<>();
        for (String s : lst) {
            if (s.length() % 2 == 0) {
                filtered.add(s);
            }
