        // Sort by length ascending, then alphabetically
        filtered.sort((a, b) -> {
            int lenDiff = Integer.compare(a.length(), b.length());
            return lenDiff != 0 ? lenDiff : a.compareTo(b);
        });

        return filtered;
    }
