     * @param x the value to return if {@code n} is prime
     * @param y the value to return if {@code n} is not prime
     * @return {@code x} if {@code n} is prime, otherwise {@code y}
     */
    public int xOrY(int n, int x, int y) {
        if (n <= 1) {
            return y; // 0 and 1 are not prime
        }
        if (n == 2) {
            return x; // 2 is the only even prime
        }
        if (n % 2 == 0) {
            return y; // even numbers greater than 2 are not prime
        }

        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return y; // found a divisor, not prime
            }
        }
        return x; // no divisors found, n is prime
    }
}
