    public String StrongestExtension(String class_name, List<String> extensions) {
        if (extensions == null || extensions.isEmpty()) {
            return class_name; // no extensions provided
        }

        String strongest = extensions.get(0);
        int strongestScore = computeScore(strongest);

        for (int i = 1; i < extensions.size(); i++) {
            String ext = extensions.get(i);
            int score = computeScore(ext);
            if (score > strongestScore) {
                strongest = ext;
                strongestScore = score;
            }
        }

        return class_name + "." + strongest;
    }

    private int computeScore(String s) {
        long upper = s.chars().filter(Character::isUpperCase).count();
        long lower = s.chars().filter(Character::isLowerCase).count();
        return (int) (upper - lower);
    }
}
