    public int doubleTheDifference(List<Object> lst) {
        long sum = 0L;
        for (Object obj : lst) {
            if (obj instanceof Number) {
                Number num = (Number) obj;
                // Only consider integral numeric types
                if (num instanceof Integer || num instanceof Long
                        || num instanceof Short || num instanceof Byte) {
                    long value = num.longValue();
                    if (value >= 0 && (value & 1L) == 1L) { // odd check
                        sum += value * value;
                    }
                }
            }
        }
        return (int) sum;
    }
