class Solution {
    /**
     * Returns true if any rotation of string {@code b} is a substring of string {@code a}.
     *
     * @param a the string to search in
     * @param b the string whose rotations are to be searched for
     * @return {@code true} if a rotation of {@code b} is found in {@code a}, otherwise {@code false}
     */
    public boolean cycpatternCheck(String a, String b) {
        int lenB = b.length();
        if (lenB == 0) {
            // An empty string is considered a substring of any string
            return true;
        }
        if (lenB > a.length()) {
            return false;
        }

        // All rotations of b are substrings of b + b
        String doubledB = b + b;

        // Check each substring of a of length lenB
        for (int i = 0; i <= a.length() - lenB; i++) {
            String sub = a.substring(i, i + lenB);
            if (doubledB.contains(sub)) {
                return true;
            }
        }
        return false;
    }
}
