import java.util.List;

public class Solution {
    public String StrongestExtension(String class_name, List<String> extensions) {
        if (extensions == null || extensions.isEmpty()) {
            return class_name; // or throw an exception if preferred
        }

        int bestStrength = Integer.MIN_VALUE;
        int bestIndex = 0;

        for (int i = 0; i < extensions.size(); i++) {
            String ext = extensions.get(i);
            int cap = 0;
            int sm = 0;

            for (int j = 0; j < ext.length(); j++) {
                char c = ext.charAt(j);
                if (Character.isUpperCase(c)) {
                    cap++;
                } else if (Character.isLowerCase(c)) {
                    sm++;
                }
            }

            int strength = cap - sm;
            if (strength > bestStrength) {
                bestStrength = strength;
                bestIndex = i;
            }
            // If strength == bestStrength, we keep the earlier one (do nothing)
        }

        return class_name + "." + extensions.get(bestIndex);
    }
}
