import java.util.*;

public class Solution {
    /**
     * Returns true if any rotation of string b is a substring of string a.
     *
     * @param a the string to search in
     * @param b the string whose rotations are to be searched
     * @return true if a contains any rotation of b, false otherwise
     */
    public boolean cycpatternCheck(String a, String b) {
        if (b == null || a == null) {
            return false;
        }
        int lenA = a.length();
        int lenB = b.length();

        if (lenB == 0) {
            // Empty string is considered a substring of any string
            return true;
        }
        if (lenB > lenA) {
            return false;
        }

        // Generate all rotations of b
        StringBuilder sb = new StringBuilder(b);
        for (int i = 0; i < lenB; i++) {
            // Check if current rotation is a substring of a
            if (a.contains(sb.toString())) {
                return true;
            }
            // Rotate: move first character to the end
            sb.append(sb.charAt(0));
            sb.deleteCharAt(0);
        }
        return false;
    }
}
