public class Solution {
    public List<Integer> evenOddCount(int num) {
        int even = 0;
        int odd = 0;

        String s = Integer.toString(num);
        int start = 0;
        if (s.charAt(0) == '-') {
            start = 1; // skip the minus sign
        }

        // Handle the special case when num is 0
        if (s.length() == 1 && s.charAt(0) == '0') {
            even = 1;
        } else {
            for (int i = start; i < s.length(); i++) {
                char c = s.charAt(i);
                int digit = c - '0';
                if (digit % 2 == 0) {
                    even++;
                } else {
                    odd++;
                }
            }
        }

        List<Integer> result = new ArrayList<>(2);
        result.add(even);
        result.add(odd);
        return result;
    }
}
