class Solution {
    public boolean rightAngleTriangle(int a, int b, int c) {
        // Sort the sides so that 'max' is the largest side
        int[] sides = {a, b, c};
        Arrays.sort(sides);
        int x = sides[0];
        int y = sides[1];
        int z = sides[2]; // largest side

        // Check triangle inequality: sum of two smaller sides must be greater than the largest
        if (x + y <= z) {
            return false;
        }

        // Use long to avoid integer overflow when squaring
        long lhs = (long) z * z;
        long rhs = (long) x * x + (long) y * y;

        return lhs == rhs;
    }
}

