public class Solution {
    public boolean rightAngleTriangle(int a, int b, int c) {
        // All sides must be positive
        if (a <= 0 || b <= 0 || c <= 0) {
            return false;
        }

        // Triangle inequality: sum of any two sides must be greater than the third
        if (a + b <= c || a + c <= b || b + c <= a) {
            return false;
        }

        // Use long to avoid integer overflow when squaring
        long aa = (long) a * a;
        long bb = (long) b * b;
        long cc = (long) c * c;

        // Check the Pythagorean theorem for all permutations
        return aa + bb == cc || aa + cc == bb || bb + cc == aa;
    }
}
