    public String findMax(List<String> words) {
        if (words == null || words.isEmpty()) {
            return "";
        }

        String bestWord = "";
        int bestUniqueCount = -1;

        for (String word : words) {
            if (word == null) {
                continue; // skip null entries
            }

            Set<Character> uniqueChars = new HashSet<>();
            for (char ch : word.toCharArray()) {
                uniqueChars.add(ch);
            }
            int count = uniqueChars.size();

            if (count > bestUniqueCount) {
                bestUniqueCount = count;
                bestWord = word;
            } else if (count == bestUniqueCount) {
                if (word.compareTo(bestWord) < 0) {
                    bestWord = word;
                }
            }
        }

        return bestWord;
    }
}
