import java.util.*;

class Solution {
    public int doAlgebra(List<String> operator, List<Integer> operand) {
        // Work on copies so the original lists are not modified
        List<String> ops = new ArrayList<>(operator);
        List<Integer> nums = new ArrayList<>(operand);

        // 1. Exponentiation (**), right‑to‑left to respect right associativity
        for (int i = ops.size() - 1; i >= 0; i--) {
            if ("**".equals(ops.get(i))) {
                double base = nums.get(i);
                double exp  = nums.get(i + 1);
                long result = Math.round(Math.pow(base, exp));
                nums.set(i, (int) result);
                nums.remove(i + 1);
                ops.remove(i);
            }
        }

        // 2. Multiplication (*) and Division (/), left‑to‑right
        for (int i = 0; i < ops.size(); ) {
            String op = ops.get(i);
            if ("*".equals(op)) {
                int res = nums.get(i) * nums.get(i + 1);
                nums.set(i, res);
                nums.remove(i + 1);
                ops.remove(i);
            } else if ("/".equals(op)) {
                int res = nums.get(i) / nums.get(i + 1); // floor division
                nums.set(i, res);
                nums.remove(i + 1);
                ops.remove(i);
            } else {
                i++; // move to next operator
            }
        }

        // 3. Addition (+) and Subtraction (-), left‑to‑right
        for (int i = 0; i < ops.size(); ) {
            String op = ops.get(i);
            if ("+".equals(op)) {
                int res = nums.get(i) + nums.get(i + 1);
                nums.set(i, res);
                nums.remove(i + 1);
                ops.remove(i);
            } else if ("-".equals(op)) {
                int res = nums.get(i) - nums.get(i + 1);
                nums.set(i, res);
                nums.remove(i + 1);
                ops.remove(i);
            } else {
                i++; // move to next operator
            }
        }

        // After all operations, the result is the sole remaining number
        return nums.get(0);
    }
}
