import java.util.*;

public class Solution {
    public int doAlgebra(List<String> operator, List<Integer> operand) {
        // Convert to postfix (Reverse Polish Notation) using the shunting‑yard algorithm
        List<String> postfix = new ArrayList<>();
        Deque<String> opStack = new ArrayDeque<>();

        for (int i = 0; i < operand.size(); i++) {
            postfix.add(String.valueOf(operand.get(i)));

            if (i < operator.size()) {
                String op = operator.get(i);
                while (!opStack.isEmpty() && shouldPop(opStack.peek(), op)) {
                    postfix.add(opStack.pop());
                }
                opStack.push(op);
            }
        }

        while (!opStack.isEmpty()) {
            postfix.add(opStack.pop());
        }

        // Evaluate the postfix expression
        Deque<Long> valStack = new ArrayDeque<>();
        for (String token : postfix) {
            if (isOperator(token)) {
                long b = valStack.pop();
                long a = valStack.pop();
                long res = applyOp(a, b, token);
                valStack.push(res);
            } else {
                valStack.push(Long.parseLong(token));
            }
        }

        return (int) valStack.pop();
    }

    private boolean isOperator(String s) {
        return s.equals("+") || s.equals("-") || s.equals("*") || s.equals("/") || s.equals("**");
    }

    private int precedence(String op) {
        switch (op) {
            case "**": return 3;
            case "*":
            case "/": return 2;
            case "+":
            case "-": return 1;
            default:  return 0;
        }
    }

    private boolean isRightAssociative(String op) {
        return op.equals("**");
    }

    private boolean shouldPop(String topOp, String currentOp) {
        int topPrec = precedence(topOp);
        int curPrec = precedence(currentOp);
        if (isRightAssociative(currentOp)) {
            return topPrec > curPrec;
        } else {
            return topPrec >= curPrec;
        }
    }

    private long applyOp(long a, long b, String op) {
        switch (op) {
            case "+": return a + b;
            case "-": return a - b;
            case "*": return a * b;
            case "/": return a / b;          // floor division for non‑negative integers
            case "**": return pow(a, b);
            default: throw new IllegalArgumentException("Unknown operator: " + op);
        }
    }

    private long pow(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result *= base;
            base *= base;
            exp >>= 1;
        }
        return result;
    }
}
