import java.util.ArrayList;
import java.util.List;

class Solution {
    public int doAlgebra(List<String> operator, List<Integer> operand) {
        // Work on copies so the original lists are not modified
        List<String> ops = new ArrayList<>(operator);
        List<Integer> nums = new ArrayList<>(operand);

        // Handle exponentiation (**), right‑to‑left associativity
        for (int i = ops.size() - 1; i >= 0; i--) {
            if (ops.get(i).equals("**")) {
                double pow = Math.pow(nums.get(i), nums.get(i + 1));
                nums.set(i, (int) Math.round(pow));
                nums.remove(i + 1);
                ops.remove(i);
            }
        }

        // Handle multiplication (*) and floor division (/), left‑to‑right
        for (int i = 0; i < ops.size(); i++) {
            String op = ops.get(i);
            if (op.equals("*")) {
                nums.set(i, nums.get(i) * nums.get(i + 1));
                nums.remove(i + 1);
                ops.remove(i);
                i--; // stay at the same index after removal
            } else if (op.equals("/")) {
                nums.set(i, nums.get(i) / nums.get(i + 1));
                nums.remove(i + 1);
                ops.remove(i);
                i--;
            }
        }

        // Handle addition (+) and subtraction (-), left‑to‑right
        for (int i = 0; i < ops.size(); i++) {
            String op = ops.get(i);
            if (op.equals("+")) {
                nums.set(i, nums.get(i) + nums.get(i + 1));
                nums.remove(i + 1);
                ops.remove(i);
                i--;
            } else if (op.equals("-")) {
                nums.set(i, nums.get(i) - nums.get(i + 1));
                nums.remove(i + 1);
                ops.remove(i);
                i--;
            }
        }

        // After all operations, the result is the sole remaining number
        return nums.get(0);
    }
}
