                i--; // stay at the same index after removal
            } else if (op.equals("/")) {
                nums.set(i, nums.get(i) / nums.get(i + 1));
                nums.remove(i + 1);
                ops.remove(i);
                i--;
            }
        }

        // Handle addition (+) and subtraction (-), left‑to‑right
        for (int i = 0; i < ops.size(); i++) {
            String op = ops.get(i);
            if (op.equals("+")) {
                nums.set(i, nums.get(i) + nums.get(i + 1));
                nums.remove(i + 1);
                ops.remove(i);
                i--;
            } else if (op.equals("-")) {
                nums.set(i, nums.get(i) - nums.get(i + 1));
                nums.remove(i + 1);
                ops.remove(i);
                i--;
            }
        }

        // After all operations, the result is the sole remaining number
        return nums.get(0);
    }
}

