import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<Integer> generateIntegers(int a, int b) {
        // Determine the inclusive range between a and b
        int lower = Math.min(a, b);
        int upper = Math.max(a, b);

        // Clamp the range to the single‑digit interval [0, 9]
        lower = Math.max(0, lower);
        upper = Math.min(9, upper);

        List<Integer> result = new ArrayList<>();

        // Collect all even digits within the clamped range
        for (int i = lower; i <= upper; i++) {
            if (i % 2 == 0) {
                result.add(i);
            }
        }

        return result;
    }
}
