class Solution {
    public boolean cycpatternCheck(String a, String b) {
        if (a == null || b == null) return false;
        int len = b.length();
        if (len == 0) return true;          // empty string is always a substring
        if (a.length() < len) return false; // cannot contain a longer substring

        String rotations = b + b;           // all rotations of b are substrings of this

        for (int i = 0; i <= a.length() - len; i++) {
            String sub = a.substring(i, i + len);
            if (rotations.contains(sub)) {
                return true;
            }
        }
        return false;
    }
}
